BEGIN;

CREATE TABLE IF NOT EXISTS schema_migrations (version TEXT PRIMARY KEY, applied_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE IF NOT EXISTS "audit_log" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "action" TEXT NOT NULL,
  "table_name" TEXT NOT NULL,
  "record_id" BIGINT,
  "user_name" TEXT DEFAULT '',
  "detail" TEXT DEFAULT '',
  "created_at" TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'),
  "module" TEXT NOT NULL DEFAULT 'shared',
  "business_no" TEXT NOT NULL DEFAULT '',
  "before_json" TEXT,
  "after_json" TEXT,
  "source" TEXT NOT NULL DEFAULT 'application',
  "user_id" BIGINT
);

CREATE TABLE IF NOT EXISTS "backup_file_trash" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "original_name" TEXT NOT NULL,
  "stored_name" TEXT NOT NULL,
  "file_size" BIGINT NOT NULL DEFAULT 0,
  "deleted_at" TEXT,
  "restored_at" TEXT,
  "purged_at" TEXT
);

CREATE TABLE IF NOT EXISTS "divisions" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" TEXT NOT NULL,
  "sort_order" BIGINT NOT NULL DEFAULT 0,
  "color" TEXT NOT NULL DEFAULT '#1976d2',
  "is_active" BIGINT NOT NULL DEFAULT 1,
  "show_in_work" BIGINT NOT NULL DEFAULT 1,
  "show_in_rd" BIGINT NOT NULL DEFAULT 1,
  "show_in_sample_info" BIGINT NOT NULL DEFAULT 1,
  "deleted_at" TEXT,
  "created_at" TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "governance_confirmations" (
  "token" TEXT,
  "module" TEXT NOT NULL,
  "start_at" TEXT NOT NULL,
  "end_at" TEXT NOT NULL,
  "request_user_id" BIGINT NOT NULL,
  "expires_at" TEXT NOT NULL,
  "used_at" TEXT,
  "created_at" TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("token")
);

CREATE TABLE IF NOT EXISTS "governance_import_batches" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "module" TEXT NOT NULL,
  "file_name" TEXT NOT NULL,
  "file_sha256" TEXT NOT NULL,
  "operator_user_id" BIGINT NOT NULL,
  "operator_username" TEXT NOT NULL,
  "total_rows" BIGINT NOT NULL DEFAULT 0,
  "inserted_rows" BIGINT NOT NULL DEFAULT 0,
  "skipped_rows" BIGINT NOT NULL DEFAULT 0,
  "created_at" TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "governance_jobs" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "module" TEXT NOT NULL,
  "job_type" TEXT NOT NULL,
  "start_at" TEXT DEFAULT '',
  "end_at" TEXT DEFAULT '',
  "operator_user_id" BIGINT NOT NULL,
  "operator_username" TEXT NOT NULL,
  "status" TEXT NOT NULL,
  "detail" TEXT NOT NULL DEFAULT '',
  "created_at" TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "help_articles" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "title" TEXT NOT NULL,
  "content_html" TEXT NOT NULL DEFAULT '',
  "toc_json" TEXT,
  "source_file" TEXT,
  "is_visible" BIGINT DEFAULT 1,
  "sort_order" BIGINT DEFAULT 0,
  "created_at" TEXT DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'),
  "updated_at" TEXT DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'),
  "deleted_at" TEXT
);

CREATE TABLE IF NOT EXISTS "help_documents" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "title" TEXT NOT NULL,
  "filename" TEXT NOT NULL,
  "file_path" TEXT NOT NULL,
  "file_type" TEXT NOT NULL,
  "file_size" BIGINT DEFAULT 0,
  "is_visible" BIGINT DEFAULT 1,
  "sort_order" BIGINT DEFAULT 0,
  "created_at" TEXT DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'),
  "updated_at" TEXT DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'),
  "page_count" BIGINT DEFAULT 0,
  "deleted_at" TEXT
);

CREATE TABLE IF NOT EXISTS "high_items" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" TEXT NOT NULL,
  "sort_order" BIGINT DEFAULT 0,
  "is_active" BIGINT NOT NULL DEFAULT 1,
  "created_at" TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "import_mappings" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "header_pattern" TEXT NOT NULL,
  "match_mode" TEXT NOT NULL DEFAULT 'contains',
  "target_table" TEXT NOT NULL,
  "default_type" TEXT DEFAULT '',
  "priority" BIGINT NOT NULL DEFAULT 100,
  "is_active" BIGINT NOT NULL DEFAULT 1,
  "created_at" TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "instruments" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "code" TEXT NOT NULL,
  "name" TEXT NOT NULL DEFAULT '',
  "instrument_type" TEXT NOT NULL,
  "is_active" BIGINT NOT NULL DEFAULT 1,
  "notes" TEXT NOT NULL DEFAULT '',
  "created_at" TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'),
  "deleted_at" TEXT
);

CREATE TABLE IF NOT EXISTS "log_archive_batches" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "archive_type" TEXT NOT NULL,
  "start_at" TEXT,
  "end_at" TEXT,
  "file_path" TEXT NOT NULL,
  "sha256" TEXT NOT NULL,
  "record_count" BIGINT NOT NULL DEFAULT 0,
  "file_size" BIGINT NOT NULL DEFAULT 0,
  "status" TEXT NOT NULL DEFAULT 'completed',
  "created_by" TEXT NOT NULL DEFAULT 'system',
  "created_at" TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'),
  "verified_at" TEXT,
  "deleted_at" TEXT
);

CREATE TABLE IF NOT EXISTS "maintenance_jobs" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "job_type" TEXT NOT NULL,
  "status" TEXT NOT NULL,
  "detail" TEXT NOT NULL DEFAULT '',
  "started_at" TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'),
  "completed_at" TEXT,
  "created_by" TEXT NOT NULL DEFAULT 'system'
);

CREATE TABLE IF NOT EXISTS "method_type_links" (
  "method_id" BIGINT NOT NULL,
  "method_type_id" BIGINT NOT NULL,
  PRIMARY KEY ("method_id", "method_type_id"),
  CONSTRAINT "uq_method_type_links_method_id" UNIQUE ("method_id")
);

CREATE TABLE IF NOT EXISTS "method_types" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" TEXT NOT NULL,
  "sort_order" BIGINT DEFAULT 0,
  "deleted_at" TEXT
);

CREATE TABLE IF NOT EXISTS "methods" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" TEXT NOT NULL,
  "full_name" TEXT DEFAULT '',
  "coefficient" DOUBLE PRECISION NOT NULL DEFAULT 1.0,
  "notes" TEXT DEFAULT '',
  "is_active" BIGINT NOT NULL DEFAULT 1,
  "created_at" TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'),
  "amount" DOUBLE PRECISION NOT NULL DEFAULT 0.0,
  "multiplier" DOUBLE PRECISION NOT NULL DEFAULT 1.0,
  "method_code" TEXT NOT NULL DEFAULT '',
  "instrument_id" BIGINT,
  "show_in_work" BIGINT NOT NULL DEFAULT 1,
  "show_in_rd" BIGINT NOT NULL DEFAULT 1,
  "show_in_sample_info" BIGINT NOT NULL DEFAULT 1,
  "is_common" BIGINT NOT NULL DEFAULT 0,
  "deleted_at" TEXT
);

CREATE TABLE IF NOT EXISTS "personnel_change_feedback_projects" (
  "feedback_id" BIGINT NOT NULL,
  "project_id" BIGINT NOT NULL,
  PRIMARY KEY ("feedback_id", "project_id")
);

CREATE TABLE IF NOT EXISTS "personnel_change_feedbacks" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "notice_no" TEXT NOT NULL,
  "lab_id" BIGINT NOT NULL,
  "responsible_user_id" BIGINT,
  "responsible_name_snapshot" TEXT NOT NULL DEFAULT '',
  "change_type" TEXT NOT NULL,
  "person_name" TEXT NOT NULL,
  "effective_at" TEXT NOT NULL,
  "notes" TEXT NOT NULL DEFAULT '',
  "status" TEXT NOT NULL DEFAULT '有效',
  "created_by_user_id" BIGINT NOT NULL,
  "created_by_username" TEXT NOT NULL,
  "created_at" TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'),
  "updated_at" TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'),
  "deleted_at" TEXT
);

CREATE TABLE IF NOT EXISTS "project_groups" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" TEXT NOT NULL,
  "sort_order" BIGINT NOT NULL DEFAULT 0,
  "show_in_work" BIGINT NOT NULL DEFAULT 1,
  "show_in_rd" BIGINT NOT NULL DEFAULT 1,
  "show_in_sample_info" BIGINT NOT NULL DEFAULT 1,
  "created_at" TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'),
  "division_id" BIGINT,
  "deleted_at" TEXT
);

-- Detection type visibility is an override layer: no row means visible.
CREATE TABLE IF NOT EXISTS "method_type_visibility" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "method_type_id" BIGINT NOT NULL REFERENCES method_types(id),
  "group_id" BIGINT NOT NULL REFERENCES project_groups(id),
  "portal" TEXT NOT NULL,
  "is_visible" BIGINT NOT NULL DEFAULT 0,
  "created_at" TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'),
  "updated_at" TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'),
  CONSTRAINT "uq_method_type_visibility" UNIQUE (method_type_id, group_id, portal),
  CONSTRAINT "ck_method_type_visibility_portal" CHECK (portal IN ('work','rd','sample_info'))
);
CREATE INDEX IF NOT EXISTS "idx_method_type_visibility_group_portal"
  ON method_type_visibility(group_id, portal, method_type_id);

CREATE TABLE IF NOT EXISTS "project_lab_links" (
  "project_id" BIGINT NOT NULL,
  "group_id" BIGINT NOT NULL,
  PRIMARY KEY ("project_id", "group_id")
);

CREATE TABLE IF NOT EXISTS "project_method_links" (
  "project_id" BIGINT NOT NULL,
  "method_id" BIGINT NOT NULL,
  PRIMARY KEY ("project_id", "method_id")
);

CREATE TABLE IF NOT EXISTS "projects" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "group_id" BIGINT NOT NULL,
  "name" TEXT NOT NULL,
  "full_name" TEXT DEFAULT '',
  "notes" TEXT DEFAULT '',
  "sort_order" BIGINT NOT NULL DEFAULT 0,
  "is_active" BIGINT NOT NULL DEFAULT 1,
  "show_in_work" BIGINT NOT NULL DEFAULT 1,
  "show_in_rd" BIGINT NOT NULL DEFAULT 1,
  "show_in_sample_info" BIGINT NOT NULL DEFAULT 1,
  "project_status" TEXT NOT NULL DEFAULT 'ongoing',
  "archived_at" TEXT,
  "archived_by" TEXT,
  "created_at" TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'),
  "coefficient" DOUBLE PRECISION NOT NULL DEFAULT 1.0,
  "method_type" TEXT NOT NULL DEFAULT '其他',
  "associated_lab_ids" TEXT NOT NULL DEFAULT '',
  "associated_method_ids" TEXT NOT NULL DEFAULT '',
  "high_item_id" BIGINT,
  "high_item" TEXT,
  "deleted_at" TEXT
);

CREATE TABLE IF NOT EXISTS "rd_record_columns" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" TEXT NOT NULL,
  "label" TEXT NOT NULL,
  "data_type" TEXT NOT NULL DEFAULT 'text',
  "width" BIGINT DEFAULT 100,
  "sort_order" BIGINT DEFAULT 0,
  "is_predefined" BIGINT NOT NULL DEFAULT 1,
  "is_required" BIGINT NOT NULL DEFAULT 0,
  "is_active" BIGINT NOT NULL DEFAULT 1,
  "show_in_list" BIGINT NOT NULL DEFAULT 1,
  "show_in_form" BIGINT NOT NULL DEFAULT 1,
  "show_in_export" BIGINT NOT NULL DEFAULT 1,
  "options" TEXT NOT NULL DEFAULT '',
  "option_detail_rules" TEXT NOT NULL DEFAULT '',
  "default_value" TEXT NOT NULL DEFAULT '',
  "placeholder" TEXT NOT NULL DEFAULT '',
  "applicable_types" TEXT NOT NULL DEFAULT '',
  "entry_row" BIGINT NOT NULL DEFAULT 1,
  "created_at" TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'),
  "updated_at" TEXT DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS "rd_work_records" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "project_id" BIGINT NOT NULL,
  "method_id" BIGINT,
  "user_name" TEXT NOT NULL,
  "quantity" BIGINT NOT NULL,
  "recorded_at" TEXT NOT NULL,
  "group_id" BIGINT,
  "created_at" TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'),
  "deleted_at" TEXT,
  "status" TEXT NOT NULL DEFAULT '待取样',
  "sampler" TEXT,
  "sampled_at" TEXT,
  "division_id" BIGINT,
  "batch_no" TEXT DEFAULT '',
  "notes" TEXT DEFAULT '',
  "high_item" TEXT,
  "business_no" TEXT NOT NULL DEFAULT '',
  "project_name_snapshot" TEXT NOT NULL DEFAULT '',
  "lab_name_snapshot" TEXT NOT NULL DEFAULT '',
  "method_name_snapshot" TEXT NOT NULL DEFAULT '',
  "high_item_snapshot" TEXT NOT NULL DEFAULT '',
  "coefficient_snapshot" DOUBLE PRECISION NOT NULL DEFAULT 1.0,
  "updated_at" TEXT,
  "last_activity_at" TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD"T"HH24:MI:SS'),
  "instrument_code_snapshot" TEXT NOT NULL DEFAULT '',
  "instrument_type_snapshot" TEXT NOT NULL DEFAULT '',
  "created_by_user_id" BIGINT,
  "created_by_username_snapshot" TEXT NOT NULL DEFAULT '',
  "instrument_id_snapshot" BIGINT,
  "subject_user_id" BIGINT,
  "detected_by" TEXT,
  "detected_at" TEXT,
  "extra_fields" TEXT NOT NULL DEFAULT '{}',
  "return_reason" TEXT NOT NULL DEFAULT '',
  "returned_by" TEXT NOT NULL DEFAULT '',
  "returned_at" TEXT,
  "return_confirmed_at" TEXT,
  "return_confirmed_by" TEXT NOT NULL DEFAULT '',
  "voided_at" TEXT,
  "voided_by" TEXT NOT NULL DEFAULT '',
  "void_reason" TEXT NOT NULL DEFAULT ''
);

CREATE TABLE IF NOT EXISTS "record_events" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "module" TEXT NOT NULL,
  "table_name" TEXT NOT NULL,
  "record_id" BIGINT NOT NULL,
  "business_no" TEXT NOT NULL DEFAULT '',
  "event_type" TEXT NOT NULL,
  "from_status" TEXT,
  "to_status" TEXT,
  "operator" TEXT NOT NULL DEFAULT '',
  "operated_at" TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'),
  "reason" TEXT NOT NULL DEFAULT '',
  "before_json" TEXT,
  "after_json" TEXT
);

CREATE TABLE IF NOT EXISTS "role_permissions" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "role_id" BIGINT NOT NULL,
  "permission_key" TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS "role_templates" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" TEXT NOT NULL,
  "description" TEXT NOT NULL DEFAULT '',
  "is_system" BIGINT NOT NULL DEFAULT 1,
  "sort_order" BIGINT NOT NULL DEFAULT 0,
  "deleted_at" TEXT
);

CREATE TABLE IF NOT EXISTS "role_template_permissions" (
  "template_id" BIGINT NOT NULL,
  "permission_key" TEXT NOT NULL,
  PRIMARY KEY ("template_id", "permission_key")
);

CREATE TABLE IF NOT EXISTS "roles" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" TEXT NOT NULL,
  "description" TEXT DEFAULT '',
  "is_system" BIGINT NOT NULL DEFAULT 0,
  "sort_order" BIGINT NOT NULL DEFAULT 0,
  "system_key" TEXT NOT NULL DEFAULT '',
  "template_id" BIGINT,
  "deleted_at" TEXT
);

CREATE TABLE IF NOT EXISTS "sample_info_attachments" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "record_id" BIGINT NOT NULL,
  "file_name" TEXT NOT NULL,
  "stored_name" TEXT NOT NULL,
  "file_size" BIGINT NOT NULL,
  "file_type" TEXT NOT NULL,
  "created_at" TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'),
  "deleted_at" TEXT
);

CREATE TABLE IF NOT EXISTS "sample_info_column_visibility" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "type_key" TEXT NOT NULL,
  "column_id" BIGINT NOT NULL,
  "is_visible" BIGINT NOT NULL DEFAULT 1,
  "is_required" BIGINT NOT NULL DEFAULT 0,
  "show_in_form" BIGINT NOT NULL DEFAULT 1,
  "show_in_list" BIGINT NOT NULL DEFAULT 1,
  "show_in_export" BIGINT NOT NULL DEFAULT 1,
  "sort_order" BIGINT NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS "sample_info_columns" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "field_key" TEXT NOT NULL,
  "label" TEXT NOT NULL,
  "data_type" TEXT NOT NULL DEFAULT 'text',
  "is_predefined" BIGINT NOT NULL DEFAULT 0,
  "is_required" BIGINT NOT NULL DEFAULT 0,
  "is_active" BIGINT NOT NULL DEFAULT 1,
  "width" BIGINT DEFAULT 100,
  "sort_order" BIGINT DEFAULT 0,
  "options" TEXT,
  "show_in_list" BIGINT NOT NULL DEFAULT 1,
  "show_in_export" BIGINT NOT NULL DEFAULT 1,
  "show_in_form" BIGINT NOT NULL DEFAULT 1,
  "created_at" TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'),
  "updated_at" TEXT DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'),
  "type_key" TEXT,
  "deleted_at" TEXT
);

CREATE TABLE IF NOT EXISTS "sample_info_records" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "status" TEXT NOT NULL DEFAULT '待取样',
  "seq_no" BIGINT NOT NULL,
  "batch_no" TEXT NOT NULL,
  "user_name" TEXT NOT NULL,
  "lab_name" TEXT NOT NULL,
  "project_name" TEXT NOT NULL,
  "submitted_at" TEXT NOT NULL,
  "detection_date" TEXT NOT NULL,
  "main_components" TEXT NOT NULL,
  "detection_type" TEXT NOT NULL,
  "notes" TEXT DEFAULT '',
  "created_at" TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'),
  "updated_at" TEXT DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'),
  "deleted_at" TEXT,
  "type_key" TEXT DEFAULT '',
  "division_id" BIGINT,
  "quantity" BIGINT NOT NULL DEFAULT 1,
  "extra_fields" TEXT DEFAULT '{}',
  "sampled_by" TEXT NOT NULL DEFAULT '',
  "sampled_at" TEXT,
  "detected_by" TEXT NOT NULL DEFAULT '',
  "business_no" TEXT NOT NULL DEFAULT '',
  "group_id" BIGINT,
  "created_by_user_id" BIGINT,
  "created_by_username_snapshot" TEXT NOT NULL DEFAULT ''
);

CREATE TABLE IF NOT EXISTS "sample_info_types" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "type_key" TEXT NOT NULL,
  "label" TEXT NOT NULL,
  "description" TEXT DEFAULT '',
  "color" TEXT DEFAULT '#2e7d32',
  "sort_order" BIGINT DEFAULT 0,
  "is_active" BIGINT NOT NULL DEFAULT 1,
  "created_at" TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'),
  "deleted_at" TEXT
);

CREATE TABLE IF NOT EXISTS "sample_records" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "project_id" BIGINT NOT NULL,
  "group_id" BIGINT NOT NULL,
  "user_name" TEXT NOT NULL,
  "sample_name" TEXT NOT NULL,
  "sample_count" BIGINT NOT NULL DEFAULT 1,
  "unit" TEXT NOT NULL DEFAULT '个',
  "batch_no" TEXT DEFAULT '',
  "notes" TEXT DEFAULT '',
  "submitted_at" TEXT NOT NULL,
  "created_at" TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'),
  "deleted_at" TEXT
);

CREATE TABLE IF NOT EXISTS "system_settings" (
  "key" TEXT,
  "value" TEXT NOT NULL,
  "updated_at" TEXT,
  PRIMARY KEY ("key")
);

CREATE TABLE IF NOT EXISTS "trash_entries" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "entity_type" TEXT NOT NULL,
  "table_name" TEXT NOT NULL,
  "record_id" BIGINT NOT NULL,
  "category" TEXT NOT NULL,
  "module" TEXT NOT NULL DEFAULT 'shared',
  "display_name" TEXT NOT NULL,
  "business_no" TEXT NOT NULL DEFAULT '',
  "snapshot_json" TEXT NOT NULL DEFAULT '{}',
  "delete_reason" TEXT NOT NULL DEFAULT '',
  "deleted_by_user_id" BIGINT,
  "deleted_by_username" TEXT NOT NULL,
  "owner_user_id" BIGINT,
  "owner_group_id" BIGINT,
  "dependency_summary" TEXT NOT NULL DEFAULT '',
  "can_purge" BIGINT NOT NULL DEFAULT 1,
  "deleted_at" TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'),
  "restored_at" TEXT,
  "restored_by_user_id" BIGINT,
  "restored_by_username" TEXT,
  "purged_at" TEXT,
  "purged_by_user_id" BIGINT,
  "purged_by_username" TEXT,
  "archive_reference" TEXT NOT NULL DEFAULT ''
);

CREATE TABLE IF NOT EXISTS "user_affiliation_group_links" (
  "user_id" BIGINT NOT NULL,
  "affiliation_group_id" BIGINT NOT NULL,
  PRIMARY KEY ("user_id", "affiliation_group_id")
);

CREATE TABLE IF NOT EXISTS "user_affiliation_groups" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "code" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "sort_order" BIGINT NOT NULL DEFAULT 0,
  "is_system" BIGINT NOT NULL DEFAULT 1
);

CREATE TABLE IF NOT EXISTS "user_roles" (
  "user_id" BIGINT NOT NULL,
  "role_id" BIGINT NOT NULL,
  "created_at" TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("user_id", "role_id")
);

CREATE TABLE IF NOT EXISTS "user_sessions" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" BIGINT NOT NULL,
  "token" TEXT NOT NULL,
  "expires_at" TEXT NOT NULL,
  "keep_signed_in" BIGINT NOT NULL DEFAULT 0,
  "last_seen_at" TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'),
  "created_at" TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'),
  "device_id" TEXT NOT NULL DEFAULT '',
  "device_name" TEXT NOT NULL DEFAULT ''
);

CREATE TABLE IF NOT EXISTS "users" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "username" TEXT NOT NULL,
  "password" TEXT NOT NULL,
  "division_id" BIGINT,
  "group_id" BIGINT,
  "is_admin" BIGINT NOT NULL DEFAULT 0,
  "is_active" BIGINT NOT NULL DEFAULT 1,
  "created_at" TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'),
  "updated_at" TEXT DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'),
  "role_id" BIGINT,
  "deleted_at" TEXT,
  "purged_at" TEXT
);

CREATE TABLE IF NOT EXISTS "work_records" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "project_id" BIGINT NOT NULL,
  "user_name" TEXT NOT NULL,
  "quantity" BIGINT NOT NULL,
  "recorded_at" TEXT NOT NULL,
  "created_at" TEXT NOT NULL DEFAULT to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS'),
  "deleted_at" TEXT,
  "batch_no" TEXT DEFAULT '',
  "extra_info" TEXT DEFAULT '',
  "method_id" BIGINT,
  "group_id" BIGINT,
  "multiplier" DOUBLE PRECISION NOT NULL DEFAULT 1.0,
  "division_id" BIGINT,
  "high_item" TEXT,
  "business_no" TEXT NOT NULL DEFAULT '',
  "project_name_snapshot" TEXT NOT NULL DEFAULT '',
  "lab_name_snapshot" TEXT NOT NULL DEFAULT '',
  "method_name_snapshot" TEXT NOT NULL DEFAULT '',
  "high_item_snapshot" TEXT NOT NULL DEFAULT '',
  "coefficient_snapshot" DOUBLE PRECISION NOT NULL DEFAULT 1.0,
  "updated_at" TEXT,
  "instrument_code_snapshot" TEXT NOT NULL DEFAULT '',
  "instrument_type_snapshot" TEXT NOT NULL DEFAULT '',
  "created_by_user_id" BIGINT,
